def solve(gi,go=None):
    from collections import deque
    H,W=len(gi),len(gi[0])
    cnt={}
    for r in gi:
        for v in r: cnt[v]=cnt.get(v,0)+1
    bg=max(cnt,key=cnt.get)
    cc=comps4c(gi,bg)
    def sil(cells):
        ys=[y for y,x in cells]; xs=[x for y,x in cells]
        s=[[' ']*(max(xs)-min(xs)+1) for _ in range(max(ys)-min(ys)+1)]
        for y,x in cells: s[y-min(ys)][x-min(xs)]='#'
        return [''.join(r) for r in s]
    multi=[(i,col,cells) for i,(col,cells) in enumerate(cc) if len(cells)>1]
    from collections import defaultdict
    groups=defaultdict(list)
    for i,col,cells in multi: groups[sil(cells)].append((i,col,cells))
    # key: color with exactly one multi-cell comp, unique sil
    keycand=[]
    colcomps=defaultdict(list)
    for i,col,cells in multi: colcomps[col].append((i,cells))
    for col,cs in colcomps.items():
        if len(cs)==1 and sum(1 for k2,g in groups.items() if len(g)==1)>0:
            sil0=sil(cs[0][1])
            if len(groups[sil0])==1: keycand.append((col,cs[0][1]))
    if len(keycand)!=1:
        # fallback: L-shape
        pass
    kcol,kcells=keycand[0]
    kys=[y for y,x in kcells]; kxs=[x for y,x in kcells]
    def boxdist(cells):
        ys=[y for y,x in cells]; xs=[x for y,x in cells]
        dy=max(min(kys)-max(ys), min(ys)-max(kys),0)
        dx=max(min(kxs)-max(xs), min(xs)-max(kxs),0)
        return max(dy,dx)
    out=[row[:] for row in gi]
    changed=[]
    for s,g in groups.items():
        if len(g)<2: continue
        cols={c for _,c,_ in g}
        if len(cols)<2: continue
        # largest pair: pick members with different colors, largest comp size
        g2=sorted(g,key=lambda t:-len(t[2]))
        # best different-color pair
        best=None
        for a in range(len(g2)):
            for b in range(a+1,len(g2)):
                if g2[a][1]!=g2[b][1]:
                    best=(g2[a],g2[b]); break
            if best: break
        a,b=best
        # recolor farther member
        src,tgt=(a,b) if boxdist(a[2])>boxdist(b[2]) else (b,a)
        for y,x in src[2]: out[y][x]=kcol
        changed.append((src[1],kcol,len(src[2])))
    return out,changed,keycand
